/** JSON-in-localStorage with an in-memory fallback when storage is refused. */
const memory = new Map<string, string>();

function backend(): Pick<Storage, "getItem" | "setItem" | "removeItem"> {
  try {
    const probe = "__krzemien_probe__";
    window.localStorage.setItem(probe, "1");
    window.localStorage.removeItem(probe);
    return window.localStorage;
  } catch {
    return {
      getItem: (k) => memory.get(k) ?? null,
      setItem: (k, v) => { memory.set(k, v); },
      removeItem: (k) => { memory.delete(k); },
    };
  }
}

export function readJson<T>(key: string): T | null {
  try {
    const raw = backend().getItem(key);
    return raw ? (JSON.parse(raw) as T) : null;
  } catch {
    return null;
  }
}
export function writeJson(key: string, value: unknown) {
  try { backend().setItem(key, JSON.stringify(value)); } catch { /* storage refused */ }
}
export function removeKey(key: string) {
  try { backend().removeItem(key); } catch { /* storage refused */ }
}
export function storageWritable(): boolean {
  try {
    const probe = "__krzemien_probe__";
    window.localStorage.setItem(probe, "1");
    window.localStorage.removeItem(probe);
    return true;
  } catch { return false; }
}
