import { useState } from "react";
import { Slider, SliderThumb, SliderTrack } from "react-aria-components";
import { formatTime } from "../../lib/format";
import { strings } from "./strings";
import s from "./ProgressSlider.module.css";

interface Props { position: number; duration: number; disabled?: boolean; onSeek: (t: number) => void; showTimes?: boolean }

export function ProgressSlider({ position, duration, disabled, onSeek, showTimes = true }: Props) {
  const [scrub, setScrub] = useState<number | null>(null);
  const max = duration > 0 ? duration : 1;
  const value = scrub ?? Math.min(position, max);
  return (
    <div className={s.wrap}>
      <Slider
        className={s.slider}
        aria-label={strings.progress}
        aria-valuetext={strings.elapsedOf(formatTime(value), formatTime(duration))}
        minValue={0}
        maxValue={max}
        step={1}
        value={value}
        isDisabled={disabled || duration <= 0}
        onChange={(v) => setScrub(Array.isArray(v) ? v[0] ?? 0 : v)}
        onChangeEnd={(v) => { const t = Array.isArray(v) ? v[0] ?? 0 : v; setScrub(null); onSeek(t); }}
      >
        <SliderTrack className={s.track}>
          {({ state }) => (
            <>
              <div className={s.bar}>
                <div className={s.fill} style={{ width: `${state.getThumbPercent(0) * 100}%` }} />
              </div>
              <SliderThumb className={s.thumb} />
            </>
          )}
        </SliderTrack>
      </Slider>
      {showTimes && (
        <div className={s.times} aria-hidden="true">
          <span>{formatTime(value)}</span>
          <span>{formatTime(duration)}</span>
        </div>
      )}
    </div>
  );
}
