import { useSyncExternalStore } from "react";
import type { ChapterEnd, NavigationTarget, ProgressTtl, Tour, TourConfig, TranscriptMode } from "./types";
import { readJson, removeKey, writeJson } from "../lib/storage";

/** Per-browser overrides of per-tour configuration, for field testing. */
export interface Overrides {
  chapterEnd?: ChapterEnd;
  navigationTarget?: NavigationTarget;
  transcriptMode?: TranscriptMode;
  progressTtl?: ProgressTtl;
}
export interface EffectiveConfig extends TourConfig { progressTtl: ProgressTtl }

const KEY = "krzemien.overrides.v1";
const listeners = new Set<() => void>();
let cache: Overrides = readJson<Overrides>(KEY) ?? {};

export const VALUES = {
  chapterEnd: ["map", "transition-audio"] as const,
  navigationTarget: ["next-point", "tour-start"] as const,
  transcriptMode: ["static", "synced"] as const,
  progressTtl: ["none", "1h", "24h", "7d"] as const,
};

export const getOverrides = () => cache;
export function setOverrides(next: Overrides) {
  cache = { ...next };
  if (Object.keys(cache).length) writeJson(KEY, cache); else removeKey(KEY);
  listeners.forEach((l) => l());
}
export function subscribeOverrides(l: () => void) { listeners.add(l); return () => { listeners.delete(l); }; }

export function effectiveConfig(tour: Tour, o: Overrides = cache): EffectiveConfig {
  return {
    chapterEnd: o.chapterEnd ?? tour.config.chapterEnd,
    navigationTarget: o.navigationTarget ?? tour.config.navigationTarget,
    transcriptMode: o.transcriptMode ?? tour.config.transcriptMode,
    progressTtl: o.progressTtl ?? "none",
  };
}

export function useTourConfig(tour: Tour): EffectiveConfig {
  const o = useSyncExternalStore(subscribeOverrides, getOverrides, getOverrides);
  return effectiveConfig(tour, o);
}

/** `?variant=chapterEnd:transition-audio,transcriptMode:synced` persists overrides and cleans the URL. */
export function applyVariantFromUrl() {
  const url = new URL(window.location.href);
  const raw = url.searchParams.get("variant");
  if (!raw) return;
  const next: Overrides = { ...cache };
  for (const pair of raw.split(",")) {
    const [k, v] = pair.split(":");
    if (!k || !v) continue;
    const key = k as keyof Overrides;
    const allowed = VALUES[key] as readonly string[] | undefined;
    if (allowed?.includes(v)) (next as Record<string, string>)[key] = v;
  }
  setOverrides(next);
  url.searchParams.delete("variant");
  window.history.replaceState(null, "", url.toString());
}
