import { Navbar } from "../components/Navbar";
import { Footer } from "../components/Footer";
import { strings } from "./PlaceholderPage.strings";
import s from "./PlaceholderPage.module.css";

export function PlaceholderPage({ kind }: { kind: "accessibility" | "privacy" }) {
  const t = strings[kind];
  return (
    <div className="page with-mini">
      <Navbar />
      <main className={s.main}>
        <h1 className="h1">{t.title}</h1>
        <div className="prose" style={{ padding: 0 }}>{strings.body.map((p, i) => <p key={i}>{p}</p>)}</div>
        <p className={s.note}>{t.note}</p>
      </main>
      <Footer />
    </div>
  );
}
