import { lazy, Suspense } from "react";
import type { ComponentProps } from "react";
import s from "./TourMap.module.css";

const TourMap = lazy(() => import("./TourMap").then((m) => ({ default: m.TourMap })));
export type { Leg } from "./TourMap";

/** Loads Leaflet only when a map is rendered; keeps the height reserved meanwhile. */
export function LazyTourMap(props: ComponentProps<typeof TourMap>) {
  return (
    <Suspense fallback={<div className={s.wrap} style={{ height: props.height ?? 240 }} aria-hidden="true"><div className={s.map} /></div>}>
      <TourMap {...props} />
    </Suspense>
  );
}
