import { useLocation, useNavigate } from "react-router";
import { usePlayer } from "./AudioEngine";
import { Controls } from "./Controls";
import { chapterRoute } from "../../content";
import { Artwork } from "../../components/Artwork";
import { strings } from "./strings";
import s from "./MiniPlayer.module.css";

export function MiniPlayer() {
  const player = usePlayer();
  const navigate = useNavigate();
  const location = useLocation();
  const { state, tour, chapter } = player;
  const show = tour && chapter && state.status !== "idle" && state.status !== "locked" && !player.headerInView;
  if (!show) return null;
  const pct = state.duration > 0 ? Math.min(100, (state.position / state.duration) * 100) : 0;
  const onChapterPage = location.pathname.includes(`/q/`) || location.pathname.endsWith(chapterRoute(tour, chapter));
  const open = () => {
    if (onChapterPage) window.scrollTo({ top: 0, behavior: "smooth" });
    else navigate(chapterRoute(tour, chapter));
  };
  return (
    <div className={s.bar} role="region" aria-label={strings.miniPlayerOpen}>
      <div className={s.progress} aria-hidden="true"><div className={s.fill} style={{ width: `${pct}%` }} /></div>
      <button type="button" className={s.open} onClick={open} aria-label={strings.miniPlayerOpen}>
        <Artwork className={s.thumb} ratio={1} seed={chapter.order - 1} alt="" pad="12%" />
        <span className={s.text}>
          <span className={s.title}>{state.track === "transition" ? strings.transitionPlaying : chapter.title}</span>
          <span className={s.sub}>{tour.title}</span>
        </span>
      </button>
      <Controls size="mini" state={state} onToggle={player.toggle} onBack10={player.back10} onReplay={player.replay} onRetry={player.retry} />
    </div>
  );
}
