import { createContext, useCallback, useContext, useEffect, useMemo, useReducer, useRef, useState, type ReactNode } from "react";
import { initialPlayerState, reduce, type PlayerState } from "./machine";
import type { Chapter, Tour } from "../../content/types";
import { assetUrl, audioUrl } from "../../lib/base";
import { track } from "../../lib/analytics";
import { effectiveConfig } from "../../content/config";
import { updateProgress } from "../progress/store";
import { markCompleted, savePosition } from "../progress/rules";
import { setMediaSession, setPlaybackState, updatePositionState } from "./mediaSession";
import { strings } from "./strings";

export type EngineEvent =
  | { type: "chapter-ended"; tourId: string; chapterId: string }
  | { type: "transition-started"; tourId: string; chapterId: string }
  | { type: "transition-ended"; tourId: string; chapterId: string };

export interface LoadOptions { position: number; locked: boolean; resumeKind: PlayerState["resumeKind"] }

export interface Engine {
  state: PlayerState;
  tour: Tour | null;
  chapter: Chapter | null;
  load: (tour: Tour, chapter: Chapter, opts: LoadOptions) => void;
  play: () => void;
  pause: () => void;
  toggle: () => void;
  seek: (time: number) => void;
  back10: () => void;
  replay: () => void;
  retry: () => void;
  subscribe: (l: (e: EngineEvent) => void) => () => void;
  headerInView: boolean;
  setHeaderInView: (v: boolean) => void;
}

const EngineContext = createContext<Engine | null>(null);
const SAVE_EVERY_MS = 5000;
const TAB_ID = Math.random().toString(36).slice(2);
const LOADING_TIMEOUT_MS = 20000;
const nowIso = () => new Date().toISOString();

export function AudioEngineProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(reduce, initialPlayerState);
  const [headerInView, setHeaderInView] = useState(false);
  const [loaded, setLoaded] = useState<{ tour: Tour; chapter: Chapter } | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const meta = useRef<{ tour: Tour | null; chapter: Chapter | null; track: "chapter" | "transition"; locked: boolean }>({ tour: null, chapter: null, track: "chapter", locked: true });
  const pendingSeek = useRef<number | null>(null);
  const lastSave = useRef(0);
  const lastPosState = useRef(0);
  const listeners = useRef(new Set<(e: EngineEvent) => void>());
  const channel = useRef<BroadcastChannel | null>(null);
  const stateRef = useRef(state);
  useEffect(() => { stateRef.current = state; }, [state]);

  const emit = useCallback((e: EngineEvent) => { listeners.current.forEach((l) => l(e)); }, []);

  const getAudio = useCallback(() => {
    if (!audioRef.current) {
      const a = document.createElement("audio");
      a.preload = "metadata";
      a.setAttribute("playsinline", "");
      audioRef.current = a;
    }
    return audioRef.current;
  }, []);

  const persistPosition = useCallback(() => {
    const { tour, chapter, track: t } = meta.current;
    const a = audioRef.current;
    if (!tour || !chapter || !a || t !== "chapter" || meta.current.locked) return;
    updateProgress((d) => savePosition(d, tour.id, chapter.id, a.currentTime, a.duration || 0, nowIso()));
    lastSave.current = Date.now();
  }, []);

  const play = useCallback(() => {
    const a = getAudio();
    if (meta.current.locked || !meta.current.chapter) return;
    const s = stateRef.current;
    if (s.status === "ended") {
      // Play again: back to the chapter from the start, whatever track ended.
      const { chapter } = meta.current;
      meta.current.track = "chapter";
      dispatch({ type: "LOAD", tourId: meta.current.tour!.id, chapterId: chapter.id, position: 0, locked: false, resumeKind: "new" });
      a.src = audioUrl(chapter.audio);
      pendingSeek.current = null;
      a.load();
    }
    dispatch({ type: "PLAY_REQUESTED" });
    channel.current?.postMessage({ type: "play", id: TAB_ID });
    track("play", { tourId: meta.current.tour?.id, chapterId: meta.current.chapter?.id, position: Math.round(a.currentTime) });
    a.play().catch((err: unknown) => {
      dispatch({ type: "ERROR", message: err instanceof Error ? err.name : "play-rejected" });
      track("error", { code: err instanceof Error ? err.name : "play-rejected" });
    });
  }, [getAudio]);

  const pause = useCallback(() => { audioRef.current?.pause(); }, []);
  const toggle = useCallback(() => {
    const s = stateRef.current;
    if (s.status === "playing" || s.status === "loading") pause(); else play();
  }, [pause, play]);

  const seek = useCallback((time: number) => {
    const a = audioRef.current;
    if (!a || meta.current.locked) return;
    const t = Math.max(0, Math.min(time, a.duration || time));
    if (a.readyState >= 1) a.currentTime = t; else pendingSeek.current = t;
    dispatch({ type: "TIME", position: t });
  }, []);
  const back10 = useCallback(() => { const a = audioRef.current; if (a) seek(a.currentTime - 10); }, [seek]);
  const replay = useCallback(() => {
    const s = stateRef.current;
    if (s.status === "ended") { play(); return; }
    seek(0);
  }, [play, seek]);

  const retry = useCallback(() => {
    const a = audioRef.current;
    const { chapter } = meta.current;
    if (!a || !chapter) return;
    const at = a.currentTime || stateRef.current.position;
    dispatch({ type: "RETRY" });
    pendingSeek.current = at;
    a.load();
    a.play().catch(() => { /* stays paused; the user can press play */ });
  }, []);

  const load = useCallback((tour: Tour, chapter: Chapter, opts: LoadOptions) => {
    const a = getAudio();
    const same = meta.current.chapter?.id === chapter.id && meta.current.track === "chapter";
    if (same && !opts.locked && !meta.current.locked && stateRef.current.status !== "idle") return; // already loaded, keep playing
    persistPosition();
    meta.current = { tour, chapter, track: "chapter", locked: opts.locked };
    setLoaded({ tour, chapter });
    dispatch({ type: "LOAD", tourId: tour.id, chapterId: chapter.id, position: opts.position, locked: opts.locked, resumeKind: opts.resumeKind });
    if (opts.locked) {
      a.pause();
      a.removeAttribute("src");
      a.load();
      setPlaybackState("none");
      return;
    }
    pendingSeek.current = opts.position > 0 ? opts.position : null;
    a.preload = "auto";
    a.src = audioUrl(chapter.audio);
    a.load();
    setMediaSession(
      { title: chapter.title, artist: tour.title, album: strings.mediaSessionAlbum, artwork: assetUrl("cover-512.png") },
      { play, pause, seekbackward: back10, seekto: seek },
    );
    const cfg = effectiveConfig(tour);
    if (cfg.chapterEnd === "transition-audio" && chapter.transitionClip) {
      const href = audioUrl(chapter.transitionClip);
      if (!document.querySelector(`link[rel="prefetch"][href="${href}"]`)) {
        const link = document.createElement("link");
        link.rel = "prefetch"; link.as = "audio"; link.href = href;
        document.head.appendChild(link);
      }
    }
  }, [back10, getAudio, pause, persistPosition, play, seek]);

  // Media element events -> state machine
  useEffect(() => {
    const a = getAudio();
    const onMeta = () => {
      dispatch({ type: "METADATA", duration: a.duration || 0 });
      if (pendingSeek.current != null) { a.currentTime = pendingSeek.current; pendingSeek.current = null; }
    };
    const onPlaying = () => { dispatch({ type: "PLAYING" }); setPlaybackState("playing"); };
    const onWaiting = () => dispatch({ type: "WAITING" });
    const onPause = () => {
      if (a.ended) return;
      dispatch({ type: "PAUSED" }); setPlaybackState("paused"); persistPosition();
    };
    const onTime = () => {
      dispatch({ type: "TIME", position: a.currentTime });
      const now = Date.now();
      if (now - lastSave.current > SAVE_EVERY_MS) persistPosition();
      if (now - lastPosState.current > 1000) { updatePositionState(a.duration, a.currentTime); lastPosState.current = now; }
    };
    const onEnded = () => {
      const { tour, chapter, track: t } = meta.current;
      if (!tour || !chapter) return;
      if (t === "chapter") {
        updateProgress((d) => markCompleted(d, tour.id, chapter.id, nowIso()));
        track("complete", { tourId: tour.id, chapterId: chapter.id });
        emit({ type: "chapter-ended", tourId: tour.id, chapterId: chapter.id });
        const cfg = effectiveConfig(tour);
        if (cfg.chapterEnd === "transition-audio" && chapter.transitionClip) {
          meta.current.track = "transition";
          dispatch({ type: "TRANSITION_LOAD" });
          a.src = audioUrl(chapter.transitionClip);
          a.load();
          a.play().then(
            () => { track("transition_play", { tourId: tour.id, chapterId: chapter.id }); emit({ type: "transition-started", tourId: tour.id, chapterId: chapter.id }); },
            (err: unknown) => { dispatch({ type: "ERROR", message: err instanceof Error ? err.name : "transition-rejected" }); track("error", { code: "transition-rejected" }); },
          );
          return;
        }
        dispatch({ type: "ENDED" });
        setPlaybackState("paused");
        const last = tour.chapters[tour.chapters.length - 1];
        if (last?.id === chapter.id) track("tour_complete", { tourId: tour.id });
        return;
      }
      dispatch({ type: "ENDED" });
      setPlaybackState("paused");
      emit({ type: "transition-ended", tourId: tour.id, chapterId: chapter.id });
    };
    const onError = () => {
      const code = a.error?.code ?? 0;
      dispatch({ type: "ERROR", message: `media-error-${code}` });
      track("error", { code, tourId: meta.current.tour?.id, chapterId: meta.current.chapter?.id });
    };
    a.addEventListener("loadedmetadata", onMeta);
    a.addEventListener("playing", onPlaying);
    a.addEventListener("waiting", onWaiting);
    a.addEventListener("stalled", onWaiting);
    a.addEventListener("pause", onPause);
    a.addEventListener("timeupdate", onTime);
    a.addEventListener("ended", onEnded);
    a.addEventListener("error", onError);
    return () => {
      a.removeEventListener("loadedmetadata", onMeta);
      a.removeEventListener("playing", onPlaying);
      a.removeEventListener("waiting", onWaiting);
      a.removeEventListener("stalled", onWaiting);
      a.removeEventListener("pause", onPause);
      a.removeEventListener("timeupdate", onTime);
      a.removeEventListener("ended", onEnded);
      a.removeEventListener("error", onError);
    };
  }, [emit, getAudio, persistPosition]);

  // Loading watchdog: 20 s without progress is an error with a retry.
  useEffect(() => {
    if (state.status !== "loading") return;
    const t = window.setTimeout(() => dispatch({ type: "ERROR", message: "timeout" }), LOADING_TIMEOUT_MS);
    return () => window.clearTimeout(t);
  }, [state.status, state.position]);

  // Online/offline, page visibility, other tabs.
  useEffect(() => {
    const onOnline = () => dispatch({ type: "OFFLINE", offline: false });
    const onOffline = () => dispatch({ type: "OFFLINE", offline: true });
    const onHide = () => { if (document.visibilityState === "hidden") persistPosition(); };
    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);
    document.addEventListener("visibilitychange", onHide);
    window.addEventListener("pagehide", persistPosition);
    if (!navigator.onLine) dispatch({ type: "OFFLINE", offline: true });
    if ("BroadcastChannel" in window) {
      const ch = new BroadcastChannel("krzemien-player");
      ch.onmessage = (ev: MessageEvent<{ type: string; id: string }>) => {
        if (ev.data?.type === "play" && ev.data.id !== TAB_ID) audioRef.current?.pause();
      };
      channel.current = ch;
    }
    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
      document.removeEventListener("visibilitychange", onHide);
      window.removeEventListener("pagehide", persistPosition);
      channel.current?.close(); channel.current = null;
    };
  }, [persistPosition]);

  const subscribe = useCallback((l: (e: EngineEvent) => void) => { listeners.current.add(l); return () => { listeners.current.delete(l); }; }, []);

  const value = useMemo<Engine>(() => ({
    state, tour: loaded?.tour ?? null, chapter: loaded?.chapter ?? null,
    load, play, pause, toggle, seek, back10, replay, retry, subscribe, headerInView, setHeaderInView,
  }), [state, loaded, load, play, pause, toggle, seek, back10, replay, retry, subscribe, headerInView]);

  return <EngineContext.Provider value={value}>{children}</EngineContext.Provider>;
}

export function usePlayer(): Engine {
  const ctx = useContext(EngineContext);
  if (!ctx) throw new Error("usePlayer outside AudioEngineProvider");
  return ctx;
}
