import type { Chapter, EffectiveConfigLike, Tour } from "./rulesTypes";
import type { ProgressState, TourProgress } from "./store";

export type ArrivalKind = "new" | "resume" | "replay" | "skip";
export interface Arrival { kind: ArrivalKind; position: number; alreadyPlayed: boolean }

const END_TOLERANCE_S = 2;

/** Arrival rule for opening chapter C's QR URL (PRD 02, "Rescans and arrival rules"). */
export function arrival(tour: Tour, chapter: Chapter, tp: TourProgress): Arrival {
  const cp = tp.chapters[chapter.id];
  const current = tour.chapters.find((c) => c.id === tp.currentChapterId) ?? null;
  const skipped = current ? chapter.order - current.order > 1 : chapter.order > 1 && Object.keys(tp.chapters).length === 0 ? false : false;
  if (cp?.completedAt) return { kind: "replay", position: 0, alreadyPlayed: true };
  if (cp && cp.position > 0) return { kind: "resume", position: cp.position, alreadyPlayed: false };
  if (skipped) return { kind: "skip", position: 0, alreadyPlayed: false };
  return { kind: "new", position: 0, alreadyPlayed: false };
}

/** Records an unlock and makes the chapter current. */
export function unlockChapter(draft: ProgressState, tour: Tour, chapter: Chapter, nowIso: string) {
  const tp = (draft.tours[tour.id] ??= { currentChapterId: null, updatedAt: nowIso, chapters: {} });
  tp.chapters[chapter.id] ??= { unlockedAt: nowIso, position: 0, completedAt: null, lastPlayedAt: null };
  tp.currentChapterId = chapter.id;
  tp.updatedAt = nowIso;
}

export function savePosition(draft: ProgressState, tourId: string, chapterId: string, position: number, duration: number, nowIso: string) {
  const tp = draft.tours[tourId];
  const cp = tp?.chapters[chapterId];
  if (!tp || !cp) return;
  cp.position = Math.max(0, position);
  cp.lastPlayedAt = nowIso;
  tp.updatedAt = nowIso;
  if (duration > 0 && duration - position <= END_TOLERANCE_S && !cp.completedAt) cp.completedAt = nowIso;
}

export function markCompleted(draft: ProgressState, tourId: string, chapterId: string, nowIso: string) {
  const tp = draft.tours[tourId];
  const cp = tp?.chapters[chapterId];
  if (!tp || !cp) return;
  cp.completedAt = cp.completedAt ?? nowIso;
  cp.position = 0;
  tp.updatedAt = nowIso;
}

export const isUnlocked = (tp: TourProgress, chapterId: string) => Boolean(tp.chapters[chapterId]);

export type ChapterStatus = "played" | "current" | "next" | "upcoming";

/** Derived status for lists and markers (PRD 02, "Chapter status"). */
export function chapterStatus(tour: Tour, tp: TourProgress, chapter: Chapter): ChapterStatus {
  if (tp.chapters[chapter.id]?.completedAt) return "played";
  if (tp.currentChapterId === chapter.id) return "current";
  const next = nextUnplayed(tour, tp);
  if (next?.id === chapter.id) return "next";
  return "upcoming";
}

/** First chapter after the current one that is not completed. */
export function nextUnplayed(tour: Tour, tp: TourProgress): Chapter | null {
  const current = tour.chapters.find((c) => c.id === tp.currentChapterId);
  const from = current ? current.order : 0;
  return tour.chapters.find((c) => c.order > from && !tp.chapters[c.id]?.completedAt) ?? null;
}

export interface NavigationResolution { target: Chapter; from: Chapter | null; reason: "next-point" | "tour-start" | "this-point" }

/** One place that decides where "Nawiguj mnie" points (PRD 03). */
export function resolveNavigationTarget(tour: Tour, tp: TourProgress, config: EffectiveConfigLike, here: Chapter | null): NavigationResolution {
  const first = tour.chapters[0]!;
  if (config.navigationTarget === "tour-start") return { target: first, from: here, reason: "tour-start" };
  const current = here ?? tour.chapters.find((c) => c.id === tp.currentChapterId) ?? null;
  const next = current ? tour.chapters.find((c) => c.order === current.order + 1) ?? null : first;
  if (next) return { target: next, from: current, reason: "next-point" };
  return { target: current ?? first, from: null, reason: "this-point" };
}
