export type PlayerStatus = "idle" | "locked" | "ready" | "loading" | "playing" | "paused" | "ended" | "error";
export type Track = "chapter" | "transition";

export interface PlayerState {
  status: PlayerStatus;
  track: Track;
  tourId: string | null;
  chapterId: string | null;
  position: number;
  duration: number;
  offline: boolean;
  error: string | null;
  /** The chapter's last playback intent; drives the primary button label. */
  resumeKind: "new" | "resume" | "replay";
}

export type PlayerEvent =
  | { type: "LOAD"; tourId: string; chapterId: string; position: number; locked: boolean; resumeKind: PlayerState["resumeKind"] }
  | { type: "UNLOAD" }
  | { type: "METADATA"; duration: number }
  | { type: "PLAY_REQUESTED" }
  | { type: "PLAYING" }
  | { type: "WAITING" }
  | { type: "PAUSED" }
  | { type: "TIME"; position: number }
  | { type: "ENDED" }
  | { type: "ERROR"; message: string }
  | { type: "RETRY" }
  | { type: "TRANSITION_LOAD" }
  | { type: "OFFLINE"; offline: boolean };

export const initialPlayerState: PlayerState = {
  status: "idle", track: "chapter", tourId: null, chapterId: null, position: 0, duration: 0, offline: false, error: null, resumeKind: "new",
};

/** Pure state table for the player (PRD 03, "States"). */
export function reduce(s: PlayerState, e: PlayerEvent): PlayerState {
  switch (e.type) {
    case "LOAD":
      return { ...initialPlayerState, offline: s.offline, tourId: e.tourId, chapterId: e.chapterId, position: e.position, status: e.locked ? "locked" : "loading", resumeKind: e.resumeKind };
    case "UNLOAD":
      return { ...initialPlayerState, offline: s.offline };
    case "OFFLINE":
      return { ...s, offline: e.offline };
    case "METADATA":
      if (s.status === "locked" || s.status === "idle") return { ...s, duration: e.duration };
      return { ...s, duration: e.duration, status: s.status === "loading" && !s.error ? "ready" : s.status };
    case "PLAY_REQUESTED":
      if (s.status === "locked" || s.status === "idle") return s;
      return { ...s, status: "loading", error: null };
    case "PLAYING":
      if (s.status === "locked" || s.status === "idle") return s;
      return { ...s, status: "playing", error: null };
    case "WAITING":
      return s.status === "playing" ? { ...s, status: "loading" } : s;
    case "PAUSED":
      if (s.status === "playing" || s.status === "loading") return { ...s, status: "paused" };
      return s;
    case "TIME":
      return s.position === e.position ? s : { ...s, position: e.position };
    case "ENDED":
      if (s.status === "locked" || s.status === "idle") return s;
      return { ...s, status: "ended", position: s.duration || s.position };
    case "ERROR":
      if (s.status === "locked" || s.status === "idle") return s;
      return { ...s, status: "error", error: e.message };
    case "RETRY":
      return s.status === "error" ? { ...s, status: "loading", error: null } : s;
    case "TRANSITION_LOAD":
      return { ...s, track: "transition", status: "loading", position: 0, duration: 0, error: null };
    default:
      return s;
  }
}

/** Which label the primary button carries in a given state. */
export function primaryAction(s: PlayerState): "play" | "pause" | "resume" | "playAgain" | "locked" {
  if (s.status === "locked" || s.status === "idle") return "locked";
  if (s.status === "playing" || s.status === "loading") return "pause";
  if (s.status === "ended") return "playAgain";
  if (s.status === "paused") return s.position > 0 ? "resume" : "play";
  if (s.resumeKind === "resume" && s.position > 0) return "resume";
  if (s.resumeKind === "replay") return "playAgain";
  return "play";
}
