import { useEffect } from "react";
import { useLocation } from "react-router";
import { Navbar } from "../components/Navbar";
import { Footer } from "../components/Footer";
import { TourCard } from "../components/TourCard";
import { PillButton } from "../components/PillButton";
import { Artwork } from "../components/Artwork";
import { site, tours } from "../content";
import { strings } from "./HomePage.strings";
import s from "./HomePage.module.css";

export function useHashScroll() {
  const { hash } = useLocation();
  useEffect(() => {
    if (!hash) return;
    const el = document.getElementById(hash.slice(1));
    el?.scrollIntoView({ behavior: "smooth", block: "start" });
  }, [hash]);
}

export function HomePage() {
  useHashScroll();
  const cards = Array.from({ length: Math.max(1, site.prototype.repeatTourCards) }, (_, i) => tours[i % tours.length]!);
  return (
    <div className="page with-mini">
      <Navbar />
      <main>
        <Artwork ratio={393 / 206} seed={2} alt="" className={s.hero} pad="6%" tone="paper" />
        <section className={s.section} aria-labelledby="about-short">
          <h1 id="about-short" className="h1 center">{strings.aboutShortHeading}</h1>
          <div className="prose">{site.aboutShort.map((p, i) => <p key={i}>{p}</p>)}</div>
        </section>
        <section id="sluchowiska" className={s.section} aria-labelledby="tours-heading">
          <h2 id="tours-heading" className="h2 center">{strings.toursHeading}</h2>
          <ul className={s.slider} aria-label={strings.toursHeading}>
            {cards.map((t, i) => <li key={`${t.id}-${i}`}><TourCard tour={t} seed={i} /></li>)}
          </ul>
        </section>
        <section id="o-projekcie" className={s.section} aria-labelledby="about-long">
          <h2 id="about-long" className="h2 center">{strings.aboutLongHeading}</h2>
          <div className="prose">{site.aboutLong.map((p, i) => <p key={i}>{p}</p>)}</div>
          <div className={s.cta}><PillButton href={site.externalLinks.dkKrzemien}>{strings.ctaDk}</PillButton></div>
        </section>
      </main>
      <Footer />
    </div>
  );
}
