/** In-memory event log standing in for an analytics provider. */
export interface AnalyticsEvent { at: string; name: string; props: Record<string, unknown> }

const MAX = 200;
const events: AnalyticsEvent[] = [];
const listeners = new Set<() => void>();

export function track(name: string, props: Record<string, unknown> = {}) {
  events.push({ at: new Date().toISOString(), name, props });
  if (events.length > MAX) events.shift();
  if (import.meta.env.DEV) console.debug("[track]", name, props);
  listeners.forEach((l) => l());
}
export const getEvents = () => events.slice().reverse();
export function subscribeEvents(l: () => void) { listeners.add(l); return () => { listeners.delete(l); }; }
