import { lazy, Suspense } from "react";
import { createBrowserRouter, RouterProvider, Outlet, ScrollRestoration } from "react-router";
import { AudioEngineProvider } from "./features/player/AudioEngine";
import { MiniPlayer } from "./features/player/MiniPlayer";
import { WebviewBanner } from "./components/WebviewBanner";
import { HomePage } from "./pages/HomePage";
import { LandingPage } from "./features/landing/LandingPage";
import { site } from "./content";
import { TourPage } from "./pages/TourPage";
import { ChapterPage } from "./pages/ChapterPage";
import { PlaceholderPage } from "./pages/PlaceholderPage";
import { NotFoundPage } from "./pages/NotFoundPage";
const QrSheetPage = lazy(() => import("./pages/QrSheetPage").then((m) => ({ default: m.QrSheetPage })));
const DiagnosticsPage = lazy(() => import("./pages/DiagnosticsPage").then((m) => ({ default: m.DiagnosticsPage })));
import { basename } from "./lib/base";

function Layout() {
  return (
    <AudioEngineProvider>
      <ScrollRestoration />
      <WebviewBanner />
      <Outlet />
      <MiniPlayer />
    </AudioEngineProvider>
  );
}

const router = createBrowserRouter(
  [
    {
      element: <Layout />,
      children: [
        { path: "/", element: site.prototype.landingActive ? <LandingPage /> : <HomePage /> },
        { path: "/home", element: <HomePage /> },
        { path: "/sluchowiska/:tourSlug", element: <TourPage /> },
        { path: "/sluchowiska/:tourSlug/:chapterSlug", element: <ChapterPage /> },
        { path: "/q/:token", element: <ChapterPage /> },
        { path: "/deklaracja-dostepnosci", element: <PlaceholderPage kind="accessibility" /> },
        { path: "/polityka-rodo", element: <PlaceholderPage kind="privacy" /> },
        { path: "/qr", element: <Suspense fallback={null}><QrSheetPage /></Suspense> },
        { path: "/diagnostyka", element: <Suspense fallback={null}><DiagnosticsPage /></Suspense> },
        { path: "*", element: <NotFoundPage /> },
      ],
    },
  ],
  { basename },
);

export function App() {
  return <RouterProvider router={router} />;
}
