/** Lock-screen and notification controls where the platform exposes them. */
export interface MediaSessionMeta { title: string; artist: string; album: string; artwork: string }
export interface MediaSessionHandlers {
  play: () => void;
  pause: () => void;
  seekbackward: () => void;
  seekto: (time: number) => void;
}

export const hasMediaSession = () => typeof navigator !== "undefined" && "mediaSession" in navigator;

export function setMediaSession(meta: MediaSessionMeta, h: MediaSessionHandlers) {
  if (!hasMediaSession()) return;
  const ms = navigator.mediaSession;
  try {
    ms.metadata = new MediaMetadata({
      title: meta.title,
      artist: meta.artist,
      album: meta.album,
      artwork: [{ src: meta.artwork, sizes: "512x512", type: "image/png" }],
    });
  } catch { /* unsupported */ }
  const set = (action: MediaSessionAction, fn: MediaSessionActionHandler | null) => {
    try { ms.setActionHandler(action, fn); } catch { /* unsupported action */ }
  };
  set("play", () => h.play());
  set("pause", () => h.pause());
  set("seekbackward", () => h.seekbackward());
  set("seekto", (d) => { if (typeof d.seekTime === "number") h.seekto(d.seekTime); });
  set("stop", () => h.pause());
}

export function setPlaybackState(state: "playing" | "paused" | "none") {
  if (!hasMediaSession()) return;
  try { navigator.mediaSession.playbackState = state; } catch { /* ignore */ }
}

export function updatePositionState(duration: number, position: number) {
  if (!hasMediaSession() || !Number.isFinite(duration) || duration <= 0) return;
  try {
    navigator.mediaSession.setPositionState?.({ duration, position: Math.min(position, duration), playbackRate: 1 });
  } catch { /* ignore */ }
}
