import { forwardRef } from "react";
import { usePlayer } from "./AudioEngine";
import { Controls } from "./Controls";
import { ProgressSlider } from "./ProgressSlider";
import { Artwork } from "../../components/Artwork";
import { IconLock } from "../../components/icons/generated";
import type { Chapter, Tour } from "../../content/types";
import { strings } from "./strings";
import s from "./PlayerHeader.module.css";

interface Props { tour: Tour; chapter: Chapter; locked: boolean; alreadyPlayed: boolean }

export const PlayerHeader = forwardRef<HTMLElement, Props>(function PlayerHeader({ tour, chapter, locked, alreadyPlayed }, ref) {
  const player = usePlayer();
  const st = player.state;
  const active = st.chapterId === chapter.id;
  const transition = active && st.track === "transition";
  const position = active ? st.position : 0;
  const duration = active ? st.duration : 0;
  return (
    <section ref={ref} className={s.header} aria-labelledby="player-title" data-locked={locked || undefined} data-testid="player-header">
      <div className={s.coverWrap}>
        <Artwork className={s.cover} ratio={1} seed={chapter.order - 1} alt={strings.coverAlt} pad="14%" />
      </div>
      <div className={s.band}>
        <ProgressSlider position={position} duration={duration} disabled={locked || !active} onSeek={player.seek} />
        <Controls
          state={active ? st : { ...st, status: locked ? "locked" : st.status }}
          onToggle={player.toggle}
          onBack10={player.back10}
          onReplay={player.replay}
          onRetry={player.retry}
        />
        {locked && (
          <p className={s.lockedHint}><IconLock className={s.lockedIcon} />{strings.lockedHint}</p>
        )}
        {st.offline && active && <p className={s.offline} role="status">{strings.offline}</p>}
      </div>
      <div className={s.titles}>
        <h1 id="player-title" className={`h1 ${s.title}`}>{transition ? strings.transitionPlaying : chapter.title}</h1>
        <p className={`h3 ${s.tour}`}>{tour.title}</p>
        <p className={`h4 ${s.narrator}`}>{tour.narrator}</p>
        {alreadyPlayed && <p className={s.note} role="status">{strings.alreadyPlayed}</p>}
      </div>
    </section>
  );
});
