import { Button } from "react-aria-components";
import { IconBack10, IconLock, IconPause, IconPlay, IconReplay } from "../../components/icons/generated";
import { primaryAction, type PlayerState } from "./machine";
import { strings } from "./strings";
import s from "./Controls.module.css";

interface Props { state: PlayerState; onToggle: () => void; onBack10: () => void; onReplay: () => void; onRetry: () => void; size?: "full" | "mini" }

export function Controls({ state, onToggle, onBack10, onReplay, onRetry, size = "full" }: Props) {
  const action = primaryAction(state);
  const locked = action === "locked";
  const busy = state.status === "loading";
  const label = { play: strings.play, pause: strings.pause, resume: strings.resume, playAgain: strings.playAgain, locked: strings.lockedLabel }[action];
  const showPause = action === "pause";
  if (size === "mini") {
    return (
      <Button className={s.miniBtn} onPress={onToggle} isDisabled={locked} aria-label={label} data-busy={busy || undefined}>
        {showPause ? <IconPause className={s.miniIcon} /> : <IconPlay className={s.miniIcon} />}
        <span className={s.spinner} aria-hidden="true" />
      </Button>
    );
  }
  return (
    <div className={s.wrap}>
      <div className={s.row}>
        <Button className={s.side} onPress={onBack10} isDisabled={locked} aria-label={strings.back10}>
          <IconBack10 className={s.sideIcon} />
        </Button>
        <Button className={s.main} onPress={onToggle} isDisabled={locked} aria-label={label} data-busy={busy || undefined}>
          {locked ? <IconLock className={s.lockIcon} /> : showPause ? <IconPause className={s.mainIcon} /> : <IconPlay className={s.mainIcon} />}
          <span className={s.spinner} aria-hidden="true" />
        </Button>
        <Button className={s.side} onPress={onReplay} isDisabled={locked} aria-label={strings.replay}>
          <IconReplay className={s.sideIcon} />
        </Button>
      </div>
      <p className={s.live} aria-live="polite">
        {busy && !locked ? strings.buffering : state.status === "error" ? strings.error : state.status === "ended" ? strings.stateAnnounce.ended : ""}
      </p>
      {state.status === "error" && (
        <Button className={s.retry} onPress={onRetry}>{strings.retry}</Button>
      )}
    </div>
  );
}
