/**
 * Root path of the bundle, with a trailing slash ("/" or "/repo/").
 *
 * In production the bundle is built with a relative base, and this module runs
 * from `<root>/assets/<chunk>.js`, so the root is one level up from the module
 * URL. That lets the same zip be unpacked at the root of a domain or under a
 * GitHub Pages project path without a rebuild. In development Vite's base is used.
 */
function detectBase(): string {
  if (import.meta.env.DEV) return import.meta.env.BASE_URL;
  try {
    const path = new URL("..", import.meta.url).pathname;
    return path.endsWith("/") ? path : `${path}/`;
  } catch {
    return "/";
  }
}

export const baseUrl: string = detectBase();
export const basename = baseUrl.replace(/\/$/, "");
export const assetUrl = (path: string) => `${baseUrl}${path.replace(/^\//, "")}`;
export const audioUrl = (file: string) => assetUrl(`audio/${file}`);
