import type { ReactNode } from "react";
import { Button, type PressEvent } from "react-aria-components";
import { Link } from "react-router";
import { IconArrowLeft, IconArrowRight } from "./icons/generated";
import s from "./PillButton.module.css";

interface Common { children: ReactNode; arrow?: "left" | "right" | "none"; className?: string }
interface AsButton extends Common { onPress: (e: PressEvent) => void; to?: never; href?: never; id?: string }
interface AsLink extends Common { to: string; onPress?: never; href?: never }
interface AsAnchor extends Common { href: string; onPress?: never; to?: never }
type Props = AsButton | AsLink | AsAnchor;

/** The outlined pill button from the mockups (29 px, 1 px border, arrow glyph). */
export function PillButton(props: Props) {
  const arrow = props.arrow ?? "right";
  const inner = (
    <>
      {arrow === "left" && <IconArrowLeft className={s.icon} />}
      <span>{props.children}</span>
      {arrow === "right" && <IconArrowRight className={s.icon} />}
    </>
  );
  const cls = `${s.pill} ${props.className ?? ""}`;
  if ("to" in props && props.to) return <Link to={props.to} className={cls}>{inner}</Link>;
  if ("href" in props && props.href) return <a href={props.href} className={cls} target="_blank" rel="noopener noreferrer">{inner}</a>;
  const { onPress, id } = props as AsButton;
  return <Button className={cls} onPress={onPress} id={id}>{inner}</Button>;
}
