import { useRef, useState } from "react";
import { useParams } from "react-router";
import { Navbar } from "../components/Navbar";
import { Footer } from "../components/Footer";
import { PillButton } from "../components/PillButton";
import { Artwork } from "../components/Artwork";
import { LazyTourMap as TourMap } from "../features/map/LazyTourMap";
import { getTourBySlug, homePath } from "../content";
import { tourProgress, useProgress } from "../features/progress/store";
import { chapterStatus } from "../features/progress/rules";
import { NotFoundPage } from "./NotFoundPage";
import { track } from "../lib/analytics";
import { strings } from "./TourPage.strings";
import s from "./TourPage.module.css";

export function TourPage() {
  const { tourSlug } = useParams();
  const tour = getTourBySlug(tourSlug);
  const progress = useProgress();
  const [fitKey, setFitKey] = useState(0);
  const mapRef = useRef<HTMLDivElement>(null);
  if (!tour) return <NotFoundPage />;
  const tp = tourProgress(progress, tour.id);
  const showRoute = () => {
    setFitKey((k) => k + 1);
    mapRef.current?.scrollIntoView({ behavior: "smooth", block: "center" });
    track("navigate_click", { tourId: tour.id, target: "tour-start", from: "tour-page" });
  };
  return (
    <div className="page with-mini">
      <Navbar />
      <main>
        <Artwork ratio={393 / 206} seed={4} alt="" pad="8%" tone="paper" />
        <div className={s.back}><PillButton to={homePath} arrow="left">{strings.back}</PillButton></div>
        <section className={s.intro} aria-labelledby="tour-title">
          <h1 id="tour-title" className="h1 center">{strings.descriptionHeading}</h1>
          <dl className={s.credits}>
            <div><dt>{strings.textAuthor}</dt><dd>{tour.textAuthor}</dd></div>
            <div><dt>{strings.narrator}</dt><dd>{tour.narrator}</dd></div>
          </dl>
          <div className="prose">{tour.longDescription.map((p, i) => <p key={i}>{p}</p>)}</div>
        </section>
        <section className={s.howTo} aria-labelledby="howto">
          <h2 id="howto" className="h2">{strings.howToHeading}</h2>
          <p>{strings.howTo}</p>
        </section>
        <Artwork ratio={393 / 206} seed={2} alt="" pad="8%" />
        <section className={s.mapSection} aria-labelledby="map-heading" ref={mapRef}>
          <div className={s.mapGrid}>
            <TourMap tour={tour} tp={tp} fitKey={fitKey} height={179} />
            <div className={s.mapText}>
              <h2 id="map-heading" className="h1">{strings.mapHeading}</h2>
              <ol className={s.addresses}>
                {tour.chapters.map((c) => (
                  <li key={c.id} data-status={chapterStatus(tour, tp, c)}>{strings.addressItem(c.order, c.point.address)}</li>
                ))}
              </ol>
              <PillButton onPress={showRoute}>{strings.navigate}</PillButton>
            </div>
          </div>
        </section>
        <section className={s.creators} aria-labelledby="creators">
          <h2 id="creators" className="h1">{strings.creators}</h2>
          <ul className={s.creatorList}>
            {tour.creators.map((c, i) => <li key={i} className={s.creator}><span className="h3">{c.name}</span><span className="h4">{c.role}</span></li>)}
          </ul>
        </section>
      </main>
      <Footer />
    </div>
  );
}
