import { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import { useParams } from "react-router";
import { Button } from "react-aria-components";
import { Footer } from "../components/Footer";
import { PillButton } from "../components/PillButton";
import { Artwork } from "../components/Artwork";
import { OnboardingNotice } from "../components/OnboardingNotice";
import { IconBarHelp, IconBarList, IconBarMap, IconBarPlay, IconCheck } from "../components/icons/generated";
import { PlayerHeader } from "../features/player/PlayerHeader";
import { Transcript } from "../features/player/Transcript";
import { usePlayer } from "../features/player/AudioEngine";
import { LazyTourMap as TourMap, type Leg } from "../features/map/LazyTourMap";
import { getChapterBySlug, getChapterByToken, nextChapter, site } from "../content";
import { useTourConfig } from "../content/config";
import { expireProgress, getProgress, tourProgress, updateProgress, useProgress } from "../features/progress/store";
import { arrival, chapterStatus, isUnlocked, resolveNavigationTarget, unlockChapter } from "../features/progress/rules";
import { readJson, writeJson } from "../lib/storage";
import { track } from "../lib/analytics";
import { roman } from "../lib/format";
import { NotFoundPage } from "./NotFoundPage";
import { strings } from "./ChapterPage.strings";
import s from "./ChapterPage.module.css";

const ONBOARDING_KEY = "krzemien.onboarding.v1";

export function ChapterPage() {
  const { token, tourSlug, chapterSlug } = useParams();
  const found = token ? getChapterByToken(token) : getChapterBySlug(tourSlug, chapterSlug);
  if (!found) return <NotFoundPage />;
  return <ChapterView tour={found.tour} chapter={found.chapter} viaToken={Boolean(token)} key={found.chapter.id} />;
}

function ChapterView({ tour, chapter, viaToken }: { tour: Parameters<typeof nextChapter>[0]; chapter: Parameters<typeof nextChapter>[1]; viaToken: boolean }) {
  const player = usePlayer();
  const config = useTourConfig(tour);
  const progress = useProgress();
  const tp = tourProgress(progress, tour.id);
  const unlocked = viaToken || isUnlocked(tp, chapter.id);
  // Arrival is decided once per mount (the component is keyed by chapter id).
  const [arr] = useState(() => arrival(tour, chapter, tourProgress(getProgress(), tour.id)));
  const alreadyPlayed = unlocked && arr.alreadyPlayed;
  const [activeLeg, setActiveLeg] = useState<Leg | null>(null);
  const [fitKey, setFitKey] = useState(0);
  const [onboarding, setOnboarding] = useState(() => !readJson<boolean>(ONBOARDING_KEY));
  const headerRef = useRef<HTMLElement>(null);
  const mapRef = useRef<HTMLDivElement>(null);
  const transcriptRef = useRef<HTMLElement>(null);
  const navigateRef = useRef<HTMLDivElement>(null);
  const loadedFor = useRef<string | null>(null);
  const next = nextChapter(tour, chapter);
  const isLast = !next;
  const finished = isLast && Boolean(tp.chapters[chapter.id]?.completedAt);

  // Arrival and loading (PRD 02 "Rescans and arrival rules").
  useEffect(() => {
    const key = `${chapter.id}:${viaToken}`;
    if (loadedFor.current === key) return;
    loadedFor.current = key;
    expireProgress(tour.id, config.progressTtl);
    const now = new Date().toISOString();
    const resumeKind = arr.kind === "resume" ? "resume" : arr.kind === "replay" ? "replay" : "new";
    if (viaToken) {
      updateProgress((d) => unlockChapter(d, tour, chapter, now));
      track("qr_scan", { tourId: tour.id, chapterId: chapter.id, firstTime: arr.kind === "new", arrival: arr.kind });
      player.load(tour, chapter, { position: arr.position, locked: false, resumeKind });
      return;
    }
    if (isUnlocked(tourProgress(getProgress(), tour.id), chapter.id)) {
      player.load(tour, chapter, { position: arr.position, locked: false, resumeKind });
    } else {
      track("locked_view", { tourId: tour.id, chapterId: chapter.id, referrer: document.referrer });
      player.load(tour, chapter, { position: 0, locked: true, resumeKind: "new" });
    }
  }, [chapter, tour, viaToken, player, config.progressTtl, arr]);

  // Sticky mini player: the header counts as visible from the first paint, then the observer takes over.
  useLayoutEffect(() => {
    player.setHeaderInView(true);
    const el = headerRef.current;
    if (!el) return;
    const io = new IntersectionObserver(([entry]) => player.setHeaderInView(Boolean(entry?.isIntersecting)), { threshold: 0.15 });
    io.observe(el);
    return () => { io.disconnect(); player.setHeaderInView(false); };
    // eslint-disable-next-line react-hooks/exhaustive-deps -- setHeaderInView is stable
  }, []);

  const showLegTo = useCallback((target: typeof chapter, from: typeof chapter | null) => {
    setActiveLeg(from && from.id !== target.id ? { from, to: target } : null);
    setFitKey((k) => k + 1);
    mapRef.current?.scrollIntoView({ behavior: "smooth", block: "start" });
  }, []);

  // Chapter end (PRD 03): highlight the leg to the next point, move focus to "Nawiguj mnie".
  useEffect(() => player.subscribe((e) => {
    if (e.chapterId !== chapter.id) return;
    if (e.type === "chapter-ended" || e.type === "transition-ended") {
      const res = resolveNavigationTarget(tour, tourProgress(getProgress(), tour.id), config, chapter);
      if (next) showLegTo(res.target, chapter);
      else { setFitKey((k) => k + 1); mapRef.current?.scrollIntoView({ behavior: "smooth", block: "start" }); }
      window.setTimeout(() => navigateRef.current?.querySelector<HTMLElement>("button")?.focus({ preventScroll: true }), 600);
    }
  }), [player, chapter, tour, config, next, showLegTo]);

  const onNavigate = () => {
    const res = resolveNavigationTarget(tour, tp, config, chapter);
    track("navigate_click", { tourId: tour.id, chapterId: chapter.id, target: res.reason, variant: config.navigationTarget });
    showLegTo(res.target, res.from);
  };
  const dismissOnboarding = () => { setOnboarding(false); writeJson(ONBOARDING_KEY, true); };
  const scrollTo = (ref: React.RefObject<HTMLElement | null>) => ref.current?.scrollIntoView({ behavior: "smooth", block: "start" });
  const targetId = activeLeg?.to.id ?? null;
  const transcriptActive = player.state.chapterId === chapter.id && player.state.track === "chapter";

  return (
    <div className="page with-mini">
      <main>
        <PlayerHeader ref={headerRef} tour={tour} chapter={chapter} locked={!unlocked} alreadyPlayed={alreadyPlayed} />
        {onboarding && unlocked && <OnboardingNotice onClose={dismissOnboarding} />}

        <section className={s.summary} aria-labelledby="summary-heading">
          <h2 id="summary-heading" className="h1 center">{strings.summaryHeading}</h2>
          <div className={s.iconBar} role="group" aria-label={strings.iconBarLabel}>
            <Button className={s.iconBtn} onPress={() => scrollTo(headerRef)} aria-label={strings.goPlayer}><IconBarPlay className={s.icon} /></Button>
            <Button className={s.iconBtn} onPress={() => scrollTo(transcriptRef)} aria-label={strings.goTranscript} isDisabled={!unlocked}><IconBarList className={s.icon} /></Button>
            <Button className={s.iconBtn} onPress={() => scrollTo(mapRef)} aria-label={strings.goMap}><IconBarMap className={s.icon} /></Button>
            <Button className={s.iconBtn} onPress={() => { setOnboarding(true); window.scrollTo({ top: 0, behavior: "smooth" }); }} aria-label={strings.help}><IconBarHelp className={s.icon} /></Button>
          </div>
          <p className={s.summaryText}>{tour.shortDescription}</p>
        </section>
        <Artwork ratio={393 / 325} seed={chapter.order + 2} alt="" pad="18%" tone="paper" />

        <section className={s.chapters} aria-labelledby="chapters-heading" ref={mapRef}>
          <h2 id="chapters-heading" className="h1">{strings.chaptersHeading}</h2>
          {finished && <p className={s.finished} role="status">{strings.tourFinished}</p>}
          <TourMap tour={tour} tp={tp} activeLeg={activeLeg} fitKey={fitKey} targetChapterId={targetId} height={240} />
          <ol className={s.list}>
            {tour.chapters.map((c) => {
              const status = chapterStatus(tour, tp, c);
              return (
                <li key={c.id} className={s.row} data-status={status} aria-current={c.id === chapter.id ? "true" : undefined}>
                  <span className={`h3 ${s.rowTitle}`}>
                    {status === "played" && <IconCheck className={s.check} />}
                    {strings.chapterLabel(roman(c.order))}
                    {status !== "played" && status !== "upcoming" && <span className={s.badge}>{status === "current" ? strings.badgeCurrent : strings.badgeNext}</span>}
                  </span>
                  <span className={`h4 ${s.rowAddress}`}>{c.point.address}</span>
                </li>
              );
            })}
          </ol>
          <div className={s.navigate} ref={navigateRef}>
            <PillButton onPress={onNavigate}>{strings.navigateMe}</PillButton>
          </div>
        </section>

        {unlocked && (
          <section className={s.transcript} aria-labelledby="transcript-heading" ref={transcriptRef}>
            <h2 id="transcript-heading" className="h2 center">{strings.transcriptHeading}</h2>
            <Transcript segments={chapter.transcript} mode={config.transcriptMode} position={player.state.position} active={transcriptActive} label={strings.transcriptHeading} />
          </section>
        )}

        <section className={s.creators} aria-labelledby="creators-heading">
          <h2 id="creators-heading" className="h1">{strings.creators}</h2>
          <ul className={s.creatorList}>
            {tour.creators.map((c, i) => <li key={i} className={s.creator}><span className="h3">{c.name}</span><span className="h4">{c.role}</span></li>)}
          </ul>
        </section>

        <section className={s.about} aria-labelledby="about-heading">
          <h2 id="about-heading" className="h2 center">{strings.aboutHeading}</h2>
          <div className="prose">{site.aboutLong.slice(0, 1).map((p, i) => <p key={i}>{p}</p>)}</div>
          <div className={s.cta}><PillButton href={site.externalLinks.dkKrzemien}>{strings.aboutCta}</PillButton></div>
        </section>
      </main>
      <Footer />
    </div>
  );
}
