import siteJson from "../../content/site.json";
import tourJson from "../../content/tours/krzemien.json";
import transcriptsJson from "../../content/tours/krzemien.transcripts.json";
import pathsJson from "../../content/tours/krzemien.paths.json";
import type { Chapter, Path, Site, Tour, TranscriptSegment } from "./types";

type RawChapter = Omit<Chapter, "order" | "transcript">;
type Transcripts = Record<string, { duration: number; segments: TranscriptSegment[] }>;

const transcripts = transcriptsJson as Transcripts;

function buildTour(): Tour {
  const raw = tourJson as unknown as Omit<Tour, "chapters" | "paths"> & { chapters: RawChapter[] };
  const chapters: Chapter[] = raw.chapters.map((c, i) => ({
    ...c,
    order: i + 1,
    transcript: transcripts[c.id]?.segments ?? [],
  }));
  const paths = (pathsJson as unknown as Array<Path & Record<string, unknown>>).map(({ fromChapterId, toChapterId, coordinates }) => ({
    fromChapterId, toChapterId, coordinates,
  }));
  return { ...raw, chapters, paths };
}

export const site = siteJson as unknown as Site;
/** Where the app's own home page lives: "/home" while the temporary landing occupies "/". */
export const homePath = site.prototype.landingActive ? "/home" : "/";
export const tours: Tour[] = [buildTour()].filter((t) => t.published);

export const getTourBySlug = (slug: string | undefined) => tours.find((t) => t.slug === slug) ?? null;
export const getTourById = (id: string) => tours.find((t) => t.id === id) ?? null;

export function getChapterByToken(token: string | undefined): { tour: Tour; chapter: Chapter } | null {
  if (!token) return null;
  for (const tour of tours) {
    const chapter = tour.chapters.find((c) => c.qrToken === token && c.published);
    if (chapter) return { tour, chapter };
  }
  return null;
}

export function getChapterBySlug(tourSlug: string | undefined, chapterSlug: string | undefined) {
  const tour = getTourBySlug(tourSlug);
  const chapter = tour?.chapters.find((c) => c.slug === chapterSlug && c.published);
  return tour && chapter ? { tour, chapter } : null;
}

export const nextChapter = (tour: Tour, chapter: Chapter): Chapter | null =>
  tour.chapters.find((c) => c.order === chapter.order + 1) ?? null;

export const pathBetween = (tour: Tour, from: Chapter, to: Chapter): Path | null =>
  tour.paths.find((p) => p.fromChapterId === from.id && p.toChapterId === to.id) ?? null;

export const tourRoute = (tour: Tour) => `/sluchowiska/${tour.slug}`;
export const chapterRoute = (tour: Tour, chapter: Chapter) => `/sluchowiska/${tour.slug}/${chapter.slug}`;
export const qrRoute = (chapter: Chapter) => `/q/${chapter.qrToken}`;
