import { Link } from "react-router";
import type { Tour } from "../content/types";
import { tourRoute } from "../content";
import { Artwork } from "./Artwork";
import s from "./TourCard.module.css";

export function TourCard({ tour, seed = 0 }: { tour: Tour; seed?: number }) {
  return (
    <Link to={tourRoute(tour)} className={s.card}>
      <Artwork ratio={101 / 75} seed={seed} alt="" className={s.image} pad="10%" />
      <span className={s.title}>{tour.title}</span>
      <span className={s.author}>{tour.textAuthor}</span>
    </Link>
  );
}
