/** Best-effort detection of in-app browsers. Never used to block anything. */
export function detectInAppBrowser(ua: string = navigator.userAgent): string | null {
  if (/FBAN|FBAV|FB_IAB/.test(ua)) return "Facebook";
  if (/Instagram/.test(ua)) return "Instagram";
  if (/Messenger/i.test(ua)) return "Messenger";
  if (/\bLine\//.test(ua)) return "LINE";
  if (/; wv\)/.test(ua)) return "Android WebView";
  const ios = /iPhone|iPad|iPod/.test(ua);
  if (ios && !/Safari\//.test(ua) && !/CriOS|FxiOS|EdgiOS/.test(ua)) return "iOS WebView";
  return null;
}
export const isStandalone = () =>
  (typeof window !== "undefined" && window.matchMedia?.("(display-mode: standalone)").matches) ||
  ("standalone" in navigator && Boolean((navigator as unknown as { standalone?: boolean }).standalone));
