import { assetUrl } from "../lib/base";
import s from "./Artwork.module.css";

/** Collage shapes from the landing design, used as stand-in artwork until real covers exist. */
export const SHAPES = ["building-orange", "shape-sand", "blob-teal", "circle-stone", "building-green", "blob-green"] as const;

interface Props {
  ratio: number;
  /** Picks the shape; chapter order or card index keeps it stable. */
  seed?: number;
  alt: string;
  className?: string;
  /** Inner padding as a CSS length or percentage. */
  pad?: string;
  tone?: "tint" | "paper" | "ink";
}

export function Artwork({ ratio, seed = 0, alt, className, pad = "12%", tone = "tint" }: Props) {
  const shape = SHAPES[((seed % SHAPES.length) + SHAPES.length) % SHAPES.length]!;
  return (
    <div
      className={`${s.frame} ${className ?? ""}`}
      data-tone={tone}
      style={{ aspectRatio: String(ratio) }}
      role={alt ? "img" : undefined}
      aria-label={alt || undefined}
      aria-hidden={alt ? undefined : true}
    >
      <img className={s.img} src={assetUrl(`landing/${shape}.webp`)} alt="" style={{ padding: pad }} loading="lazy" draggable={false} />
    </div>
  );
}
