import { useEffect, useRef } from "react";
import type { TranscriptMode, TranscriptSegment } from "../../content/types";
import s from "./Transcript.module.css";

interface Props { segments: TranscriptSegment[]; mode: TranscriptMode; position: number; active: boolean; label: string }
const MANUAL_SCROLL_HOLD_MS = 5000;

export function Transcript({ segments, mode, position, active, label }: Props) {
  const box = useRef<HTMLDivElement>(null);
  const manualUntil = useRef(0);
  const synced = mode === "synced" && active;
  const currentIndex = synced ? segments.findIndex((seg) => seg.start != null && seg.end != null && position >= seg.start && position < seg.end) : -1;

  useEffect(() => {
    if (!synced || currentIndex < 0 || Date.now() < manualUntil.current) return;
    const el = box.current?.querySelector<HTMLElement>(`[data-i="${currentIndex}"]`);
    el?.scrollIntoView({ block: "center", behavior: "smooth" });
  }, [currentIndex, synced]);

  return (
    <div
      ref={box}
      className={s.box}
      role="region"
      aria-label={label}
      // eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex -- a scrollable region must be keyboard reachable (WCAG 2.1.1)
      tabIndex={0}
      onScroll={(e) => { if (e.isTrusted) manualUntil.current = Date.now() + MANUAL_SCROLL_HOLD_MS; }}
      onWheel={() => { manualUntil.current = Date.now() + MANUAL_SCROLL_HOLD_MS; }}
      onTouchMove={() => { manualUntil.current = Date.now() + MANUAL_SCROLL_HOLD_MS; }}
    >
      <p className={s.text}>
        {segments.map((seg, i) => (
          <span key={i} data-i={i} className={s.seg} data-current={i === currentIndex || undefined}>{seg.text}{" "}</span>
        ))}
      </p>
    </div>
  );
}
