import { useSyncExternalStore } from "react";
import type { ProgressTtl } from "../../content/types";
import { readJson, removeKey, writeJson } from "../../lib/storage";

export interface ChapterProgress {
  unlockedAt: string;
  position: number;
  completedAt: string | null;
  lastPlayedAt: string | null;
}
export interface TourProgress {
  currentChapterId: string | null;
  updatedAt: string;
  chapters: Record<string, ChapterProgress>;
}
export interface ProgressState { version: 1; tours: Record<string, TourProgress> }

const KEY = "krzemien.progress.v1";
const EMPTY: ProgressState = { version: 1, tours: {} };
const TTL_MS: Record<ProgressTtl, number | null> = { none: null, "1h": 3_600_000, "24h": 86_400_000, "7d": 7 * 86_400_000 };

const listeners = new Set<() => void>();
let state: ProgressState = sanitize(readJson<ProgressState>(KEY));

function sanitize(raw: ProgressState | null): ProgressState {
  if (!raw || raw.version !== 1 || typeof raw.tours !== "object") return { ...EMPTY, tours: {} };
  return raw;
}

export const getProgress = () => state;
export function subscribeProgress(l: () => void) { listeners.add(l); return () => { listeners.delete(l); }; }
export function useProgress(): ProgressState {
  return useSyncExternalStore(subscribeProgress, getProgress, getProgress);
}

export function updateProgress(fn: (draft: ProgressState) => void) {
  const draft: ProgressState = JSON.parse(JSON.stringify(state)) as ProgressState;
  fn(draft);
  state = draft;
  writeJson(KEY, state);
  listeners.forEach((l) => l());
}

export function clearProgress(tourId?: string) {
  if (tourId) updateProgress((d) => { delete d.tours[tourId]; });
  else { state = { ...EMPTY, tours: {} }; removeKey(KEY); listeners.forEach((l) => l()); }
}

/** Drops a tour's progress when it is older than the configured TTL. */
export function expireProgress(tourId: string, ttl: ProgressTtl, now = Date.now()) {
  const ms = TTL_MS[ttl];
  const tp = state.tours[tourId];
  if (!ms || !tp) return;
  if (now - Date.parse(tp.updatedAt) > ms) updateProgress((d) => { delete d.tours[tourId]; });
}

export const tourProgress = (s: ProgressState, tourId: string): TourProgress =>
  s.tours[tourId] ?? { currentChapterId: null, updatedAt: new Date(0).toISOString(), chapters: {} };
