import { useState } from "react";
import { detectInAppBrowser } from "../lib/webview";
import { IconClose } from "./icons/generated";
import s from "./WebviewBanner.module.css";

const KEY = "krzemien.webview-banner";
const strings = {
  text: (app: string) => `Otwarto w aplikacji ${app}. Otwórz tę stronę w przeglądarce, aby odtwarzanie działało w tle.`,
  copy: "Skopiuj adres",
  copied: "Skopiowano",
  close: "Zamknij",
};

export function WebviewBanner() {
  const [dismissed, setDismissed] = useState(() => { try { return sessionStorage.getItem(KEY) === "1"; } catch { return false; } });
  const [copied, setCopied] = useState(false);
  const app = detectInAppBrowser();
  if (!app || dismissed) return null;
  const close = () => { setDismissed(true); try { sessionStorage.setItem(KEY, "1"); } catch { /* ignore */ } };
  const copy = async () => { try { await navigator.clipboard.writeText(window.location.href); setCopied(true); } catch { /* ignore */ } };
  return (
    <div className={s.banner} role="status">
      <p className={s.text}>{strings.text(app)}</p>
      <button type="button" className={s.action} onClick={copy}>{copied ? strings.copied : strings.copy}</button>
      <button type="button" className={s.close} onClick={close} aria-label={strings.close}><IconClose className={s.closeIcon} /></button>
    </div>
  );
}
